/* ===== REGRA OFICIAL DE UNIDADE =====
   Materiais cuja família cadastrada começa com ALÇA ou CADARÇO são MT; todo o restante é KG. */
(function(){
  var unidadeOficial=function(x){try{
    var cod='',descricao='';
    if(x&&typeof x==='object'){cod=String(x.pr||x.codigo||'');descricao=String(x.desc||x.descricao||'');}else cod=String(x||'');
    var chave=cod.toUpperCase().replace(/\s+/g,'').trim();
    if(typeof VL!=='undefined'&&Array.isArray(VL)){
      var reg=VL.find(function(v){return String(v.codigo||'').toUpperCase().replace(/\s+/g,'')===chave;});
      if(reg)descricao=String(reg.descricao||reg.desc||reg.nome||descricao||'');
    }
    if(!descricao&&typeof descOf==='function')descricao=descOf(chave)||'';
    var d=String(descricao||cod).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/^[^A-Z]+/,'');
    return /^(ALCA|CADARC)/.test(d)?'MT':'KG';
  }catch(e){return 'KG';}};
  unitOf=unidadeOficial;window.unitOf=unidadeOficial;window.unitOfReal=unidadeOficial;
})();

